vec2 Z = vec2(0.0,0.0); // mess about with this
vec2 offset = vec2(-0.15,0.85); // or this
struct mandlbrot{vec2 C; vec2 z;};
int maxCheck = 100;
float manT(mandlbrot m)
{
    for(int i = 0; i<maxCheck; i++){
        m.z = vec2(pow(abs(m.z.x),2.0)-pow(abs(m.z.y),2.0),2.0*m.z.x*m.z.y)+m.C;
        if(length(m.z)>=100.0){
            return 1.0 - (float(i)/float(maxCheck));
        }
    }
    return 0.0;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float zoom = iTime*iTime+100.0;
    mandlbrot plane = mandlbrot(fragCoord/zoom-((iResolution.xy/zoom)/2.0)+offset, Z);

    vec3 col = vec3(manT(plane));

    fragColor = vec4(col,1.0);
}
